  2	
  3	import br.com.marealta.domain.*;
  4	import br.com.marealta.repository.MessageRepository;
  5	import br.com.marealta.repository.ReservationRepository;
  6	import br.com.marealta.repository.RoomRepository;
  7	import br.com.marealta.service.MessageService;
  8	import br.com.marealta.service.ReportService;
  9	import br.com.marealta.service.ReservationService;
 10	import br.com.marealta.web.dto.*;
 11	import com.fasterxml.jackson.databind.ObjectMapper;
 12	import com.fasterxml.jackson.databind.SerializationFeature;
 13	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
 14	import com.zaxxer.hikari.HikariConfig;
 15	import com.zaxxer.hikari.HikariDataSource;
 16	import io.javalin.Javalin;
 17	import io.javalin.http.Context;
 18	import io.javalin.json.JavalinJackson;
 19	
 20	import javax.sql.DataSource;
 21	import java.time.LocalDate;
 22	import java.time.YearMonth;
 23	import java.time.format.DateTimeParseException;
 24	
 25	public class Application {
 26	
 27	    public static void main(String[] args) {
 28	        DataSource dataSource = createDataSource();
 29	
 30	        RoomRepository roomRepository = new RoomRepository(dataSource);
 31	        ReservationRepository reservationRepository = new ReservationRepository(dataSource);
 32	        MessageRepository messageRepository = new MessageRepository(dataSource);
 33	
 34	        roomRepository.initSchema();
 35	        roomRepository.initData();
 36	        reservationRepository.initSchema();
 37	        messageRepository.initSchema();
 38	
 39	        MessageService messageService = new MessageService(messageRepository);
 40	        ReservationService reservationService = new ReservationService(reservationRepository, roomRepository, messageService);
 41	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 42	
 43	        ObjectMapper objectMapper = new ObjectMapper()
 44	            .registerModule(new JavaTimeModule())
 45	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 46	
 47	        int port = getPort();
 48	
 49	        Javalin app = Javalin.create(config -> {
 50	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 51	        }).start(port);
 52	
 53	        app.get("/rooms", ctx -> {
 54	            var rooms = roomRepository.findAll().stream()
 55	                .map(RoomDTO::from)
 56	                .toList();
 57	            ctx.json(rooms);
 58	        });
 59	
 60	        app.post("/reservations", ctx -> {
 61	            try {
 62	                CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
 63	
 64	                validateRequired(request.roomNumber(), "roomNumber");
 65	                validateRequired(request.guestName(), "guestName");
 66	                validateRequired(request.guestEmail(), "guestEmail");
 67	                validateRequired(request.guestCpf(), "guestCpf");
 68	                validateRequired(request.checkIn(), "checkIn");
 69	                validateRequired(request.checkOut(), "checkOut");
 70	                validateRequired(request.guests(), "guests");
 71	                validateRequired(request.ratePlan(), "ratePlan");
 72	
 73	                LocalDate checkIn = parseDate(request.checkIn(), "checkIn");
 74	                LocalDate checkOut = parseDate(request.checkOut(), "checkOut");
 75	                DateRange dateRange = new DateRange(checkIn, checkOut);
 76	
 77	                Reservation reservation = reservationService.createReservation(
 78	                    request.roomNumber(),
 79	                    request.guestName(),
 80	                    request.guestEmail(),
 81	                    request.guestCpf(),
 82	                    dateRange,
 83	                    request.guests(),
 84	                    request.ratePlan(),
 85	                    request.companyCode()
 86	                );
 87	
 88	                ctx.status(201).json(ReservationDTO.from(reservation));
 89	
 90	            } catch (Reservation.CapacityValidationException e) {
 91	                ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
 92	            } catch (IllegalArgumentException e) {
 93	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
 94	            } catch (ReservationService.RoomNotFoundException e) {
 95	                ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
 96	            } catch (ReservationService.RoomUnavailableException e) {
 97	                ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
 98	            }
 99	        });
100	
101	        app.get("/reservations/{id}", ctx -> {
102	            try {
103	                Long id = ctx.pathParamAsClass("id", Long.class).get();
104	                Reservation reservation = reservationService.getReservation(id);
105	                ctx.json(ReservationDTO.from(reservation));
106	            } catch (ReservationService.ReservationNotFoundException e) {
107	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
108	            }
109	        });
110	
111	        app.post("/reservations/{id}/confirmation", ctx -> {
112	            try {
113	                Long id = ctx.pathParamAsClass("id", Long.class).get();
114	                Reservation reservation = reservationService.confirmReservation(id);
115	                ctx.json(ReservationDTO.from(reservation));
116	            } catch (ReservationService.ReservationNotFoundException e) {
117	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
118	            } catch (IllegalStateException e) {
119	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
120	            }
121	        });
122	
123	        app.post("/reservations/{id}/cancellation", ctx -> {
124	            try {
125	                Long id = ctx.pathParamAsClass("id", Long.class).get();
126	                Reservation reservation = reservationService.cancelReservation(id);
127	                ctx.json(ReservationDTO.from(reservation));
128	            } catch (ReservationService.ReservationNotFoundException e) {
129	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
130	            } catch (IllegalStateException e) {
131	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
132	            }
133	        });
134	
135	        app.post("/reservations/{id}/check-in", ctx -> {
136	            try {
137	                Long id = ctx.pathParamAsClass("id", Long.class).get();
138	                Reservation reservation = reservationService.checkIn(id);
139	                ctx.json(ReservationDTO.from(reservation));
140	            } catch (ReservationService.ReservationNotFoundException e) {
141	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
142	            } catch (IllegalStateException e) {
143	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
144	            }
145	        });
146	
147	        app.post("/reservations/{id}/check-out", ctx -> {
148	            try {
149	                Long id = ctx.pathParamAsClass("id", Long.class).get();
150	                Reservation reservation = reservationService.checkOut(id);
151	                ctx.json(DocumentDTO.from(reservation));
152	            } catch (ReservationService.ReservationNotFoundException e) {
153	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
154	            } catch (IllegalStateException e) {
155	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
156	            }
157	        });
158	
159	        app.get("/reservations/{id}/document", ctx -> {
160	            try {
161	                Long id = ctx.pathParamAsClass("id", Long.class).get();
162	                Reservation reservation = reservationService.getReservation(id);
163	
164	                if (!reservation.getStatus().isPaid()) {
165	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Document only available for paid reservations"));
166	                    return;
167	                }
168	
169	                ctx.json(DocumentDTO.from(reservation));
170	            } catch (ReservationService.ReservationNotFoundException e) {
171	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
172	            }
173	        });
174	
175	        app.get("/messages", ctx -> {
176	            var messages = messageService.getAllMessages().stream()
177	                .map(MessageDTO::from)
178	                .toList();
179	            ctx.json(messages);
180	        });
181	
182	        app.get("/reports/occupancy", ctx -> {
183	            try {
184	                String dateStr = ctx.queryParam("date");
185	                if (dateStr == null || dateStr.isBlank()) {
186	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Date parameter is required"));
187	                    return;
188	                }
189	
190	                LocalDate date = parseDate(dateStr, "date");
191	                String csv = reportService.generateOccupancyReport(date);
192	                ctx.contentType("text/csv; charset=utf-8").result(csv);
193	            } catch (IllegalArgumentException e) {
194	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
195	            }
196	        });
197	
198	        app.get("/reports/revenue", ctx -> {
199	            try {
200	                String monthStr = ctx.queryParam("month");
201	                if (monthStr == null || monthStr.isBlank()) {
202	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Month parameter is required"));
203	                    return;
204	                }
205	
206	                YearMonth month = parseMonth(monthStr);
207	                String csv = reportService.generateRevenueReport(month);
208	                ctx.contentType("text/csv; charset=utf-8").result(csv);
209	            } catch (IllegalArgumentException e) {
210	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
211	            }
212	        });
213	
214	        app.exception(Exception.class, (e, ctx) -> {
215	            e.printStackTrace();
216	            ctx.status(500).json(new ErrorResponse("INTERNAL_ERROR", "An unexpected error occurred"));
217	        });
218	    }
219	
220	    private static DataSource createDataSource() {
221	        String url = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
222	        String user = System.getenv().getOrDefault("DB_USER", "postgres");
223	        String password = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
224	
225	        HikariConfig config = new HikariConfig();
226	        config.setJdbcUrl(url);
227	        config.setUsername(user);
228	        config.setPassword(password);
229	        config.setMaximumPoolSize(10);
230	
231	        return new HikariDataSource(config);
232	    }
233	
234	    private static int getPort() {
235	        String portEnv = System.getenv("PORT");
236	        if (portEnv != null && !portEnv.isBlank()) {
237	            return Integer.parseInt(portEnv);
238	        }
239	        return 7070;
240	    }
241	
242	    private static void validateRequired(Object value, String fieldName) {
243	        if (value == null || (value instanceof String s && s.isBlank())) {
244	            throw new IllegalArgumentException("Field '" + fieldName + "' is required");
245	        }
246	    }
247	
248	    private static LocalDate parseDate(String dateStr, String fieldName) {
249	        try {
250	            return LocalDate.parse(dateStr);
251	        } catch (DateTimeParseException e) {
252	            throw new IllegalArgumentException("Invalid date format for '" + fieldName + "': expected yyyy-MM-dd");
253	        }
254	    }
255	
256	    private static YearMonth parseMonth(String monthStr) {
257	        try {
258	            return YearMonth.parse(monthStr);
259	        } catch (DateTimeParseException e) {
260	            throw new IllegalArgumentException("Invalid month format: expected yyyy-MM");
261	        }
262	    }
263	}

