    20	    public int nights() {
    21	        return (int) checkIn.datesUntil(checkOut).count();
    22	    }
    23	
    24	    public List<LocalDate> getNights() {
    25	        List<LocalDate> nights = new ArrayList<>();
    26	        LocalDate current = checkIn;
    27	        while (current.isBefore(checkOut)) {
    28	            nights.add(current);
    29	            current = current.plusDays(1);
    30	        }
    31	        return nights;
    32	    }
    33	
    34	    public boolean isHighSeason(LocalDate date) {
    35	        Month month = date.getMonth();
    36	        int day = date.getDayOfMonth();
    37	
    38	        if (month == Month.JULY) {
    39	            return true;
    40	        }
    41	
    42	        if (month == Month.DECEMBER && day >= 15) {
    43	            return true;
    44	        }
    45	
    46	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    47	            return true;
    48	        }
    49	
    50	        return false;
    51	    }
    52	
    53	    public Money calculateNightlyTotal(Money baseRate) {
    54	        Money total = Money.zero();
    55	        for (LocalDate night : getNights()) {
    56	            Money nightRate = baseRate;
    57	            if (isHighSeason(night)) {
    58	                nightRate = nightRate.multiply(1.20);
    59	            }
    60	            total = total.add(nightRate);
    61	        }
    62	        return total;
    63	    }
