     8	public class DocumentService {
     9	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    10	
    11	    public static String buildReceipt(Reservation reservation) {
    12	        StringBuilder sb = new StringBuilder();
    13	
    14	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
    15	        sb.append("Hóspede: ").append(reservation.getGuestName())
    16	          .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
    17	        sb.append("Quarto: ").append(reservation.getRoomNumber())
    18	          .append(" (").append(reservation.getRoomType()).append(")\n");
    19	        sb.append("Entrada: ").append(reservation.getDateRange().checkIn().format(DATE_FORMATTER))
    20	          .append(" | Saída: ").append(reservation.getDateRange().checkOut().format(DATE_FORMATTER))
    21	          .append(" | ").append(formatNights(reservation.getDateRange().nights())).append("\n");
    22	
    23	        Money subtotal = reservation.calculateSubtotal();
    24	        Money discount = reservation.calculateDiscount();
    25	        Money total = reservation.calculateTotal();
    26	
    27	        sb.append("Diárias: ").append(formatMoney(subtotal)).append("\n");
    28	
    29	        if (discount.isPositive()) {
    30	            sb.append("Desconto: ").append(formatMoney(discount)).append("\n");
    31	        }
    32	
    33	        sb.append("Total: ").append(formatMoney(total));
    34	
    35	        return sb.toString();
    36	    }
    37	
    38	    private static String formatCpf(String cpf) {
    39	        if (cpf.length() == 11) {
    40	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
    41	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
    42	        }
    43	        return cpf;
    44	    }
    45	
    46	    private static String formatNights(int nights) {
    47	        return nights == 1 ? "1 diária" : nights + " diárias";
    48	    }
    49	
    50	    private static String formatMoney(Money money) {
    51	        return String.format("R$ %,.2f", money.amount()).replace(",", "X").replace(".", ",").replace("X", ".");
    52	    }
    53	}
