     1	package br.com.marealta.repository;
     2	
     3	import br.com.marealta.domain.Message;
     4	
     5	import javax.sql.DataSource;
     6	import java.sql.*;
     7	import java.util.ArrayList;
     8	import java.util.List;
     9	
    10	public class MessageRepository {
    11	    private final DataSource dataSource;
    12	
    13	    public MessageRepository(DataSource dataSource) {
    14	        this.dataSource = dataSource;
    15	    }
    16	
    17	    public void initSchema() {
    18	        String createTable = """
    19	            CREATE TABLE IF NOT EXISTS messages (
    20	                id SERIAL PRIMARY KEY,
    21	                channel VARCHAR(50) NOT NULL,
    22	                recipient VARCHAR(255) NOT NULL,
    23	                subject VARCHAR(500) NOT NULL,
    24	                body TEXT NOT NULL
    25	            )
    26	            """;
    27	
    28	        try (Connection conn = dataSource.getConnection();
    29	             Statement stmt = conn.createStatement()) {
    30	            stmt.execute(createTable);
    31	        } catch (SQLException e) {
    32	            throw new RuntimeException("Failed to create messages table", e);
    33	        }
    34	    }
    35	
    36	    public Message save(Message message) {
    37	        String insert = "INSERT INTO messages (channel, recipient, subject, body) VALUES (?, ?, ?, ?)";
    38	
    39	        try (Connection conn = dataSource.getConnection();
    40	             PreparedStatement stmt = conn.prepareStatement(insert, Statement.RETURN_GENERATED_KEYS)) {
    41	
    42	            stmt.setString(1, message.getChannel());
    43	            stmt.setString(2, message.getTo());
    44	            stmt.setString(3, message.getSubject());
    45	            stmt.setString(4, message.getBody());
    46	
    47	            stmt.executeUpdate();
    48	
    49	            try (ResultSet rs = stmt.getGeneratedKeys()) {
    50	                if (rs.next()) {
    51	                    message.setId(rs.getLong(1));
    52	                }
    53	            }
    54	
    55	            return message;
    56	        } catch (SQLException e) {
    57	            throw new RuntimeException("Failed to save message", e);
    58	        }
    59	    }
    60	
    61	    public List<Message> findAll() {
    62	        String query = "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id";
    63	        List<Message> messages = new ArrayList<>();
    64	
    65	        try (Connection conn = dataSource.getConnection();
    66	             Statement stmt = conn.createStatement();
    67	             ResultSet rs = stmt.executeQuery(query)) {
    68	
    69	            while (rs.next()) {
    70	                messages.add(mapRow(rs));
    71	            }
    72	        } catch (SQLException e) {
    73	            throw new RuntimeException("Failed to find messages", e);
    74	        }
    75	
    76	        return messages;
    77	    }
    78	
    79	    private Message mapRow(ResultSet rs) throws SQLException {
    80	        Long id = rs.getLong("id");
    81	        String channel = rs.getString("channel");
    82	        String recipient = rs.getString("recipient");
    83	        String subject = rs.getString("subject");
    84	        String body = rs.getString("body");
    85	        return new Message(id, channel, recipient, subject, body);
    86	    }
    87	}
